package com.nodecockpit.customization;
import org.junit.Test;import static org.junit.Assert.*;import java.nio.*;
public class CardMergeUniformsTest {
 @Test public void singleShapeKeepsAllOldUniformsAndDisablesSecondary(){byte[] old=new byte[240];for(int i=0;i<old.length;i++)old[i]=(byte)i;byte[] n=CardMergeUniforms.extend(old,null);assertEquals(272,n.length);for(int i=0;i<240;i++)assertEquals(old[i],n[i]);for(int i=240;i<n.length;i++)assertEquals(0,n[i]);}
 @Test public void nativeGeometryAndOpticsHaveExactShaderOffsets(){float[] shape={100,200,60,80,30,250,220,70,90,18,40,6,.75f};ByteBuffer b=ByteBuffer.wrap(CardMergeUniforms.extend(new byte[240],shape)).order(ByteOrder.nativeOrder());assertEquals(100,b.getFloat(16),0);assertEquals(30,b.getFloat(32),0);assertEquals(250,b.getFloat(240),0);assertEquals(18,b.getFloat(256),0);assertEquals(40,b.getFloat(260),0);assertEquals(6,b.getFloat(264),0);assertEquals(.75,b.getFloat(268),0);}
 @Test public void smoothUnionConnectsNarrowGapsAndSeparatesFarShapes(){assertTrue(CardMergeUniforms.union(5,5,40)<0);assertTrue(CardMergeUniforms.union(25,25,40)>0);assertEquals(-5,CardMergeUniforms.union(-5,200,40),0);assertEquals(CardMergeUniforms.union(7,13,40),CardMergeUniforms.union(13,7,40),.0001);}
 @Test(expected=IllegalArgumentException.class)public void invalidGeometryCannotReachShader(){float[] s=new float[13];s[0]=Float.NaN;CardMergeUniforms.extend(new byte[240],s);}
 @Test public void generatedShaderActuallyUsesRestoredSecondShapeAndBoundedDiffusion(){String s=CardLiquidMergeShader.SOURCE;assertTrue(s.contains("uniform float4 u[17]"));assertTrue(s.contains("sdRoundedBox(p - (u[15]).xy, (u[15]).zw, u[16].x)"));assertTrue(s.contains("sminPoly(d, d2, u[16].y)"));assertTrue(s.contains("col=mix(col,mergedBlur(cG),u[16].w)"));assertFalse(s.contains("(float4(0.0))"));assertFalse(s.contains("return half4(0.0);"));assertFalse(s.contains("return half4(half3(col * cov), half(cov));"));assertTrue(s.contains("return content.eval(coord);"));assertTrue(s.contains("mix(untouched,half4(half3(col)*untouched.a,untouched.a),half(cov))"));}
}
